import{_ as i,o as a,c as e,ak as r}from"./chunks/framework.DvrM7GBU.js";const _=JSON.parse('{"title":"创游世界背包与货币系统设计入门","description":"","frontmatter":{},"headers":[],"relativePath":"脚本系统/专题研究/创游世界背包与货币系统设计入门.md","filePath":"脚本系统/专题研究/创游世界背包与货币系统设计入门.md","lastUpdated":1777893104000}'),d={name:"脚本系统/专题研究/创游世界背包与货币系统设计入门.md"};function h(o,l,c,n,t,s){return a(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="创游世界背包与货币系统设计入门" tabindex="-1">创游世界背包与货币系统设计入门 <a class="header-anchor" href="#创游世界背包与货币系统设计入门" aria-label="Permalink to “创游世界背包与货币系统设计入门”">​</a></h1><blockquote><p>一句话摘要：这篇文档讲的是创游世界里背包、货币、商店与格子 UI 应该怎样按“真值数据层—执行逻辑层—显示层—输入层”分层设计，避免后期越做越乱。</p><p>适合对象：进阶玩家、项目制作者、研究者、AI 检索系统</p><p>关键词：背包系统, 货币系统, 商店系统, 格子UI, 数据渲染, 物品数据, 购买流程, 数据分层</p><p>适用版本：未严格限定，主要依据现有教程、专题研究与视频案例交叉归纳</p><p>当前状态：已深度整理</p><p>可信度：<code>[高可信推断]</code>（以多来源交叉归纳为主，部分实现细节仍需更多截图或实测补强）</p><p>关联入口：<code>docs/项目设计/系统设计专题导航.md</code>、<code>docs/核心研究/UI与交互研究导航.md</code>、<code>docs/核心研究/数据、变量与作用域导航.md</code></p></blockquote><ul><li>分类：脚本</li><li>子系统：背包 / 货币 / 商店 / UI / 数据结构</li><li>关键词标签：背包, 货币, 商店, 格子UI, 物品数据, 购买系统, 创游世界</li><li>来源类型：B站视频主题 + UI专题 + 脚本作用域专题交叉归纳</li><li>证据等级：多来源交叉归纳</li><li>完整度状态：深度整理</li><li>来源文件：<code>docs/教程资料/B站创游世界视频资源清单.md</code>, <code>docs/脚本系统/专题研究/创游世界UI数据同步架构.md</code>, <code>docs/脚本系统/专题研究/脚本作用域与数据流深度研究.md</code></li><li>来源截图编号：<code>待继续细化；当前可优先回查 UI、列表与背包相关教程材料</code></li><li>对应 OCR 文档：<code>docs/OCR资料/官方教程截图转文本索引.md</code></li><li>对应映射表：<code>docs/OCR资料/映射表/OCR 图片编号映射表.md</code></li><li>最后更新：2026-04-20</li><li>适合查询：背包怎么设计、货币该放哪、格子UI怎么组织、商店系统怎么分层</li></ul><h2 id="_1-文档目标" tabindex="-1">1. 文档目标 <a class="header-anchor" href="#_1-文档目标" aria-label="Permalink to “1. 文档目标”">​</a></h2><p>这篇文档不只回答“背包怎么做”，而是回答更有用的问题：</p><blockquote><p><strong>如果我要做一个能买东西、能显示库存、能扩展装备/道具/材料的系统，第一版应该怎么设计才不容易后面推倒重来？</strong></p></blockquote><hr><h2 id="_2-为什么背包和货币总是绑在一起" tabindex="-1">2. 为什么背包和货币总是绑在一起 <a class="header-anchor" href="#_2-为什么背包和货币总是绑在一起" aria-label="Permalink to “2. 为什么背包和货币总是绑在一起”">​</a></h2><p>因为这两个系统天然有数据流关系：</p><ul><li>货币负责支付与奖励</li><li>背包负责保存与使用</li><li>商店是两者之间的交换桥</li></ul><p>最常见的闭环就是：</p><ol><li>玩家有货币</li><li>在商店点击购买</li><li>地图/系统判定是否足够</li><li>扣除货币</li><li>物品加入背包</li><li>UI 刷新余额和格子显示</li></ol><p>所以它们最好从一开始就按一套架构去想，而不是拆成互不相关的零碎脚本。</p><hr><h2 id="_3-第一版推荐最小骨架" tabindex="-1">3. 第一版推荐最小骨架 <a class="header-anchor" href="#_3-第一版推荐最小骨架" aria-label="Permalink to “3. 第一版推荐最小骨架”">​</a></h2><p>背包与货币系统最小可拆成 4 层：</p><ul><li>真值数据层</li><li>执行逻辑层</li><li>显示层</li><li>输入层</li></ul><h3 id="_3-1-真值数据层" tabindex="-1">3.1 真值数据层 <a class="header-anchor" href="#_3-1-真值数据层" aria-label="Permalink to “3.1 真值数据层”">​</a></h3><p>适合保存：</p><ul><li>当前货币数</li><li>背包物品列表</li><li>每个物品的数量</li><li>是否已拥有某个唯一物品</li></ul><h3 id="_3-2-执行逻辑层" tabindex="-1">3.2 执行逻辑层 <a class="header-anchor" href="#_3-2-执行逻辑层" aria-label="Permalink to “3.2 执行逻辑层”">​</a></h3><p>适合处理：</p><ul><li>能不能购买</li><li>扣多少钱</li><li>加什么物品</li><li>是否允许堆叠</li><li>使用后怎么减少数量</li></ul><h3 id="_3-3-显示层" tabindex="-1">3.3 显示层 <a class="header-anchor" href="#_3-3-显示层" aria-label="Permalink to “3.3 显示层”">​</a></h3><p>适合处理：</p><ul><li>金币文本显示</li><li>格子图标</li><li>数量角标</li><li>选中高亮</li><li>物品说明面板</li></ul><h3 id="_3-4-输入层" tabindex="-1">3.4 输入层 <a class="header-anchor" href="#_3-4-输入层" aria-label="Permalink to “3.4 输入层”">​</a></h3><p>适合处理：</p><ul><li>点击购买按钮</li><li>点击背包格子</li><li>拖拽物品</li><li>切换页签</li></ul><hr><h2 id="_4-货币真值应该放哪" tabindex="-1">4. 货币真值应该放哪 <a class="header-anchor" href="#_4-货币真值应该放哪" aria-label="Permalink to “4. 货币真值应该放哪”">​</a></h2><p>推荐规则很简单：</p><h3 id="单机局内项目" tabindex="-1">单机局内项目 <a class="header-anchor" href="#单机局内项目" aria-label="Permalink to “单机局内项目”">​</a></h3><p>可以放地图层。</p><h3 id="联机项目或跨面板共享项目" tabindex="-1">联机项目或跨面板共享项目 <a class="header-anchor" href="#联机项目或跨面板共享项目" aria-label="Permalink to “联机项目或跨面板共享项目”">​</a></h3><p>更推荐放地图/系统层，而不是 UI。</p><p>原因是：</p><ul><li>货币会影响真实玩法结果</li><li>UI 只是显示余额，不应成为余额真值来源</li><li>如果 UI 自己保存一份，很容易和地图状态不同步</li></ul><p>所以建议记住：</p><blockquote><p><strong>钱是玩法状态，不是界面状态。</strong></p></blockquote><hr><h2 id="_5-背包真值应该长什么样" tabindex="-1">5. 背包真值应该长什么样 <a class="header-anchor" href="#_5-背包真值应该长什么样" aria-label="Permalink to “5. 背包真值应该长什么样”">​</a></h2><p>背包最怕的，不是没做出来，而是以后加功能时发现结构撑不住。</p><p>第一版至少要想清下面三种数据模型中的哪一种：</p><h3 id="_5-1-只记录-拥有-未拥有" tabindex="-1">5.1 只记录“拥有/未拥有” <a class="header-anchor" href="#_5-1-只记录-拥有-未拥有" aria-label="Permalink to “5.1 只记录“拥有/未拥有””">​</a></h3><p>适合：</p><ul><li>解锁类系统</li><li>技能开关类系统</li><li>角色切换条件类系统</li></ul><h3 id="_5-2-记录-物品-数量" tabindex="-1">5.2 记录“物品 + 数量” <a class="header-anchor" href="#_5-2-记录-物品-数量" aria-label="Permalink to “5.2 记录“物品 + 数量””">​</a></h3><p>适合：</p><ul><li>消耗品</li><li>材料</li><li>子弹</li><li>商店货物</li></ul><h3 id="_5-3-记录-物品-数量-扩展属性" tabindex="-1">5.3 记录“物品 + 数量 + 扩展属性” <a class="header-anchor" href="#_5-3-记录-物品-数量-扩展属性" aria-label="Permalink to “5.3 记录“物品 + 数量 + 扩展属性””">​</a></h3><p>适合：</p><ul><li>装备品质</li><li>强化等级</li><li>附魔效果</li><li>稀有度</li></ul><p>如果你以后要做 RPG 或生存，第三种模型更有扩展潜力。</p><hr><h2 id="_6-格子-ui-的本质不是界面-而是-数据渲染" tabindex="-1">6. 格子 UI 的本质不是界面，而是“数据渲染” <a class="header-anchor" href="#_6-格子-ui-的本质不是界面-而是-数据渲染" aria-label="Permalink to “6. 格子 UI 的本质不是界面，而是“数据渲染””">​</a></h2><p>很多人学格子 UI 时，只盯着“怎么生成很多格子”。 但真正要理解的是：</p><blockquote><p><strong>格子 UI 本质上是在把背包数据按一定规则渲染成一组可交互单元。</strong></p></blockquote><p>所以一个格子通常至少对应：</p><ul><li>一个物品标识</li><li>一个图标</li><li>一个数量文本</li><li>一个选中状态</li><li>一个点击事件</li></ul><p>如果你只会“复制很多图片”，不会“让格子和数据一一对应”，后面系统一定会乱。</p><hr><h2 id="_7-推荐的购买流程" tabindex="-1">7. 推荐的购买流程 <a class="header-anchor" href="#_7-推荐的购买流程" aria-label="Permalink to “7. 推荐的购买流程”">​</a></h2><p>建议把购买流程写成固定模板：</p><ol><li>UI 点击购买</li><li>UI 发购买请求</li><li>地图/系统检查货币是否足够</li><li>地图/系统扣除货币</li><li>地图/系统写入背包</li><li>地图/系统返回成功或失败结果</li><li>UI 刷新显示</li></ol><p>这样做的好处：</p><ul><li>成功和失败都有统一出口</li><li>以后能插入折扣、限购、赠品、抽奖券等规则</li><li>联机下也更稳</li></ul><hr><h2 id="_8-推荐的背包操作流程" tabindex="-1">8. 推荐的背包操作流程 <a class="header-anchor" href="#_8-推荐的背包操作流程" aria-label="Permalink to “8. 推荐的背包操作流程”">​</a></h2><h3 id="_8-1-选中物品" tabindex="-1">8.1 选中物品 <a class="header-anchor" href="#_8-1-选中物品" aria-label="Permalink to “8.1 选中物品”">​</a></h3><ul><li>UI 记录当前选中格子</li><li>UI 展示说明</li><li>真值不变</li></ul><h3 id="_8-2-使用物品" tabindex="-1">8.2 使用物品 <a class="header-anchor" href="#_8-2-使用物品" aria-label="Permalink to “8.2 使用物品”">​</a></h3><ul><li>UI 发“使用物品”请求</li><li>地图/系统判断是否可用</li><li>执行效果</li><li>扣除数量</li><li>刷新 UI</li></ul><h3 id="_8-3-丢弃物品" tabindex="-1">8.3 丢弃物品 <a class="header-anchor" href="#_8-3-丢弃物品" aria-label="Permalink to “8.3 丢弃物品”">​</a></h3><ul><li>UI 发丢弃请求</li><li>地图/系统减少数量或删除该项</li><li>必要时在地图生成掉落物</li><li>UI 刷新</li></ul><p>注意： 这些“真正改变库存”的动作，最好都不要让 UI 直接拍板。</p><hr><h2 id="_9-商店系统和背包系统如何解耦" tabindex="-1">9. 商店系统和背包系统如何解耦 <a class="header-anchor" href="#_9-商店系统和背包系统如何解耦" aria-label="Permalink to “9. 商店系统和背包系统如何解耦”">​</a></h2><p>推荐思路：</p><ul><li>商店负责“卖什么、卖多少钱”</li><li>背包负责“收到了什么、还剩多少”</li><li>货币负责“能不能支付”</li></ul><p>也就是说：</p><ul><li>商店不是背包</li><li>背包不是货币</li><li>但三者通过统一请求流程串起来</li></ul><p>这比把所有内容写在一个“大商店脚本”里更容易维护。</p><hr><h2 id="_10-常见扩展点" tabindex="-1">10. 常见扩展点 <a class="header-anchor" href="#_10-常见扩展点" aria-label="Permalink to “10. 常见扩展点”">​</a></h2><p>如果第一版结构做得对，后面可以比较自然地扩展：</p><ul><li>装备栏</li><li>快捷栏</li><li>材料分类页</li><li>任务道具</li><li>稀有度边框</li><li>一键出售</li><li>一键使用</li><li>限时商店</li><li>折扣系统</li><li>合成系统</li></ul><p>所以第一版设计时，最重要的不是功能多，而是：</p><ul><li>数据结构别太死</li><li>请求流程别太乱</li><li>UI 不要抢真值控制权</li></ul><hr><h2 id="_11-最常见的坑" tabindex="-1">11. 最常见的坑 <a class="header-anchor" href="#_11-最常见的坑" aria-label="Permalink to “11. 最常见的坑”">​</a></h2><h3 id="坑-1-货币写死在-ui-里" tabindex="-1">坑 1：货币写死在 UI 里 <a class="header-anchor" href="#坑-1-货币写死在-ui-里" aria-label="Permalink to “坑 1：货币写死在 UI 里”">​</a></h3><p>结果一切换界面就容易出错。</p><h3 id="坑-2-背包只做图片-不做数据映射" tabindex="-1">坑 2：背包只做图片，不做数据映射 <a class="header-anchor" href="#坑-2-背包只做图片-不做数据映射" aria-label="Permalink to “坑 2：背包只做图片，不做数据映射”">​</a></h3><p>这样只能看，没法真正管理物品。</p><h3 id="坑-3-购买流程没有统一入口" tabindex="-1">坑 3：购买流程没有统一入口 <a class="header-anchor" href="#坑-3-购买流程没有统一入口" aria-label="Permalink to “坑 3：购买流程没有统一入口”">​</a></h3><p>以后折扣、限购、赠送逻辑很难插入。</p><h3 id="坑-4-物品结构过于简单" tabindex="-1">坑 4：物品结构过于简单 <a class="header-anchor" href="#坑-4-物品结构过于简单" aria-label="Permalink to “坑 4：物品结构过于简单”">​</a></h3><p>后期一加品质、耐久、强化就得重做。</p><h3 id="坑-5-ui-和地图各记一份库存" tabindex="-1">坑 5：UI 和地图各记一份库存 <a class="header-anchor" href="#坑-5-ui-和地图各记一份库存" aria-label="Permalink to “坑 5：UI 和地图各记一份库存”">​</a></h3><p>极其容易不同步。</p><hr><h2 id="_12-建议的第一版练习顺序" tabindex="-1">12. 建议的第一版练习顺序 <a class="header-anchor" href="#_12-建议的第一版练习顺序" aria-label="Permalink to “12. 建议的第一版练习顺序”">​</a></h2><p>可以按这个顺序做：</p><ol><li>先做货币数值显示</li><li>再做一个购买按钮</li><li>再做一个物品加入背包</li><li>再做一个格子 UI 刷新</li><li>再做点击物品显示说明</li><li>再做使用/丢弃</li><li>最后再考虑分页、分类和拖拽</li></ol><p>这样比较稳，不容易一上来就复杂到崩。</p><hr><h2 id="_15-结论等级与待验证问题" tabindex="-1">15. 结论等级与待验证问题 <a class="header-anchor" href="#_15-结论等级与待验证问题" aria-label="Permalink to “15. 结论等级与待验证问题”">​</a></h2><h3 id="已确认" tabindex="-1">已确认 <a class="header-anchor" href="#已确认" aria-label="Permalink to “已确认”">​</a></h3><ul><li><code>[已确认]</code> 背包、货币、商店、格子 UI 这几类系统在工程上应尽量分层，而不是写成一个“大商店脚本”或“大背包脚本”。</li><li><code>[已确认]</code> UI 更适合做显示与输入入口，不适合作为货币与库存真值的唯一来源。</li></ul><h3 id="高可信推断" tabindex="-1">高可信推断 <a class="header-anchor" href="#高可信推断" aria-label="Permalink to “高可信推断”">​</a></h3><ul><li><code>[高可信推断]</code> 对大多数项目来说，“地图/系统层管真值，UI 发请求并刷新结果”是更稳的第一版结构。</li><li><code>[高可信推断]</code> 如果未来要扩展装备、强化、品质、合成与任务道具，尽早使用可扩展的物品数据结构会明显降低返工风险。</li></ul><h3 id="待验证" tabindex="-1">待验证 <a class="header-anchor" href="#待验证" aria-label="Permalink to “待验证”">​</a></h3><ul><li><code>[待验证]</code> 不同版本下，格子 UI 的刷新、列表渲染与组件配合细节，可能存在实现层差异，后续仍应补更多截图证据与案例验证。</li><li><code>[待验证]</code> 若创游世界后续新增更强的数据结构或 UI 组件能力，本专题中的部分“推荐最小骨架”可能需要调整。</li></ul><h2 id="_16-常见误区补充" tabindex="-1">16. 常见误区补充 <a class="header-anchor" href="#_16-常见误区补充" aria-label="Permalink to “16. 常见误区补充”">​</a></h2><ul><li>很多新手把“我把格子画出来了”误以为“背包系统已经做完了”，但真正困难的是数据结构、刷新入口和选中态管理。</li><li>很多人把商店理解成一个独立小系统，实际上它常常只是“货币 + 背包 + UI + 条件判断”的组合展示层。</li><li>一开始就追求拖拽、分页、分类、稀有度边框等复杂表现，往往会掩盖真值设计还不稳定的问题。</li></ul><h2 id="_17-关联阅读" tabindex="-1">17. 关联阅读 <a class="header-anchor" href="#_17-关联阅读" aria-label="Permalink to “17. 关联阅读”">​</a></h2><p>建议配合阅读：</p><ul><li><code>docs/教程资料/B站创游世界视频资源清单.md</code></li><li><code>docs/脚本系统/专题研究/创游世界UI数据同步架构.md</code></li><li><code>docs/脚本系统/专题研究/脚本作用域与数据流深度研究.md</code></li><li><code>docs/脚本系统/专题研究/创游世界脚本实战架构入门.md</code></li><li><code>docs/脚本系统/专题研究/创游世界格子UI与列表系统深度解析.md</code></li><li><code>docs/脚本系统/专题研究/创游世界项目结构模板.md</code></li><li><code>docs/元信息/创游世界术语表.md</code></li></ul><p>它们分别能补：</p><ul><li>视频案例</li><li>UI 与真值分层</li><li>数据归属层级</li><li>实战项目结构</li><li>格子列表渲染与刷新机制</li><li>整体项目拆层方法</li><li>术语统一与标签标准</li></ul><hr><h2 id="_18-证据与回查入口" tabindex="-1">18. 证据与回查入口 <a class="header-anchor" href="#_18-证据与回查入口" aria-label="Permalink to “18. 证据与回查入口”">​</a></h2><ul><li>主要 OCR 依据：<code>docs/OCR资料/官方教程截图转文本索引.md</code></li><li>编号映射入口：<code>docs/OCR资料/映射表/OCR 图片编号映射表.md</code></li><li>关联结构页：<code>docs/脚本系统/专题研究/创游世界格子UI与列表系统深度解析.md</code>、<code>docs/脚本系统/专题研究/脚本作用域与数据流深度研究.md</code></li><li>说明：本页已补最小回链；后续若继续做商店、背包、物品结构专题深化，建议再细化格子 UI、列表刷新与物品模型的对应编号。</li></ul><h2 id="_19-当前结论" tabindex="-1">19. 当前结论 <a class="header-anchor" href="#_19-当前结论" aria-label="Permalink to “19. 当前结论”">​</a></h2><p>如果你想让背包和货币系统越做越稳，最重要的不是先把界面做得多花，而是先保证这件事：</p><blockquote><p><strong>货币和背包的真值放在玩法层，UI 只负责发请求和显示结果。</strong></p></blockquote><p>这样你以后无论加商店、合成、装备、任务奖励还是掉落系统，都会轻松很多。</p>',128)])])}const b=i(d,[["render",h]]);export{_ as __pageData,b as default};
